#!/bin/bash
# HISTORICAL. This script built the first test/JPL-3solver-20micron (2026-09-16) out of the two single-phase cases:
# MOSE + ICE(partE) + IGLOO(partL), same material, HALF loading each. The case of the repository has since been
# regenerated by ATLAS from its input.ini (both phases mirrored at the axis): the script refuses to run while the
# case exists, and what it writes is not the case of the repository.
set -eu
export LC_ALL=C
H=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
LAG=$H/test/JPL-Lagrangian-20micron
EUL=$H/test/JPL-Eulerian-20micron
C=$H/test/JPL-3solver-20micron
[ -e "$C" ] && { echo "$C exists -- remove it first"; exit 1; }
mkdir -p "$C/INPUT" "$C/OUTPUT"
cp -rp "$LAG/MESH" "$C/"; cp -p "$LAG/JPL_chang.dat" "$LAG/jpl_compare.py" "$C/"
cp -p "$LAG"/INPUT/gas-* "$C/INPUT/"
# Lagrangian phase: the Lagrangian case's files (bc: f3=400 axis outflow, f4=301 trap wall)
for f in phase.txt properties.dat bc.txt; do cp -p "$LAG/INPUT/part-$f" "$C/INPUT/partL-$f"; done
# Eulerian phase: the Eulerian case's files (bc: f3=200, f4=300; ic.tec)
for f in phase.txt properties.dat bc.txt ic.tec; do cp -p "$EUL/INPUT/part-$f" "$C/INPUT/partE-$f"; done
# half loading on both inlets: krho 0.30 -> 0.17647 (krho/(1-krho) = 0.21429 = half of 0.42857)
for f in partL partE; do
  n=$(grep -c '^   0.30000E+00   0.10000E+01' "$C/INPUT/$f-bc.txt")
  sed -i 's/^   0.30000E+00   0.10000E+01/   0.17647E+00   0.10000E+01/' "$C/INPUT/$f-bc.txt"
  echo "$f-bc.txt: $n inlet payload(s) set to krho = 0.17647"
done
# The Eulerian IC carries the full (krho = 0.30) loading; halve rho_p and n_p so the initial field matches the inlet.
python3 - "$C/INPUT/partE-ic.tec" <<'EOF'
import sys, re
p = sys.argv[1]; txt = open(p).read()
hdr_end = txt.index('\n', txt.index('VARLOCATION')) + 1
head, body = txt[:hdr_end], txt[hdr_end:]
names = re.findall(r'"([^"]+)"', re.search(r'VARIABLES\s*=\s*(.*)', head).group(1))
z = re.search(r'I\s*=\s*(\d+).*?J\s*=\s*(\d+).*?K\s*=\s*(\d+)', head, re.S); I, J, K = map(int, z.groups())
nn, nc = I*J*K, (I-1)*(J-1)*(K-1)
toks = body.split()
out, pos = [], 0
for n in names:
    cnt = nn if n in ('x','y','z') else nc
    chunk = toks[pos:pos+cnt]; pos += cnt
    if n.startswith('rp_') or n.startswith('np_'):   # condensed density and number density
        chunk = ['%.15E' % (float(v.replace('D','E'))*0.5) for v in chunk]
    out.append(chunk)
assert pos == len(toks), (pos, len(toks))
lines = [' ' + v for chunk in out for v in chunk]           # one value per line, as ATLAS wrote it
open(p, 'w').write(head + '\n'.join(lines) + '\n')
print('partE-ic.tec: rp_* and np_* halved (%s)' % ', '.join(names))
EOF
# INI: Lagrangian INI with the Lagrangian key renamed, ICE enabled, ICE sections from the Eulerian INI
sed -e 's/^IGLOO-iter *=.*/IGLOO-iter    = 2\nICE-iter      = 250/' \
    -e 's/^phase = part .*/phase = partL     ; Lagrangian phase (ATLAS name)/' "$LAG/input.ini" > "$C/input.ini"
# only the [ICE-*] block of the Eulerian INI (it precedes the ATLAS sections there; stop at the first of them,
# dropping the ATLAS banner comment that introduces them)
awk '/^\[ICE-Parameters\]/{on=1} on && /^; -{20,}/{buf=buf $0 "\n"; next} on && /^\[(GRIB|GPB|ICB|BCB)-/{exit} on{printf "%s", buf; buf=""; print}' "$EUL/input.ini" \
  | sed -e 's/^phase = part .*/phase = partE     ; Eulerian phase (ATLAS name)/' >> "$C/input.ini"
# GPB: two condensed phases with distinct names; face keys: half loading
python3 - "$C/input.ini" <<'EOF'
import sys, re
p = sys.argv[1]; s = open(p).read()
s = s.replace('''[GPB-Phase2]
type = condensed-dispersed
modeling = lagrangian   ; ATLAS: lagrangian (IGLOO) | eulerian (ICE)
name = part
rho  = 4004.62
cp   = 1380
''', '''[GPB-Phase2]
type     = condensed-dispersed
modeling = eulerian      ; ATLAS: lagrangian (IGLOO) | eulerian (ICE)
name     = partE
rho      = 4004.62
cp       = 1380

[GPB-Phase3]
type     = condensed-dispersed
modeling = lagrangian
name     = partL
rho      = 4004.62
cp       = 1380
''')
s = re.sub(r'^krho = 0\.30$', 'krho = 0.17647   ; HALF loading per phase: two phases -> total mass-flux ratio 0.42857 as in the single-phase cases', s, flags=re.M)
s = s.replace('; JPL nozzle (Chang 1980), 20 micron particles -- MOSE + IGLOO Lagrangian coupling.',
'''; JPL nozzle (Chang 1980), 20 micron particles -- MOSE + ICE (Eulerian, phase partE) + IGLOO (Lagrangian,
; phase partL): the SAME material solved twice, each phase carrying HALF the loading (krho = 0.17647 each,
; total mass-flux ratio 0.42857 = the single-phase cases), so the gas is comparable to Chang MPL and the two
; condensed fields can be compared against each other on the same gas. Built 2026-09-16 from
; JPL-Lagrangian-20micron (partL files, INI) + JPL-Eulerian-20micron (partE files, ICE sections).''')
open(p, 'w').write(s); print('input.ini assembled')
EOF
cat > "$C/README.md" <<'EOF'
# JPL-3solver-20micron

MOSE + ICE (`partE`) + IGLOO (`partL`) on the Chang (1980) JPL nozzle, 20 µm alumina, **same material in both
condensed phases, half the loading each** (`krho = 0.17647` per phase, total mass-flux ratio 0.42857 = the
single-phase cases). Each solver reads only its own file set:

| solver | INI key | files |
|---|---|---|
| ICE   | `[ICE-Parameters] phase = partE` | `INPUT/partE-{phase.txt,properties.dat,bc.txt,ic.tec}` — bc from JPL-Eulerian (f3=200, f4=300), ic with rho_p/n_p halved |
| IGLOO | `[IGLOO-General] phase = partL`  | `INPUT/partL-{phase.txt,properties.dat,bc.txt}` — bc from JPL-Lagrangian (f3=400 axis outflow, f4=301 trap wall) |

The two bc files are deliberately DIFFERENT (that is the point of "each solver reads its own file"). The
files were copied by hand from the two single-phase cases (2026-09-16); ATLAS can regenerate them once it
writes per-phase BC payloads (plan A1) and the `modeling` token (A4) — the f3/f4 patches of `partL-bc.txt`
are still not ATLAS-expressible.

Run: `figaro hydra-MI2 -p 4 solve` (≈ 15 min). Compare: `python3 jpl_compare.py`.
Full double loading instead: set `krho` back to `0.30000E+00` in both bc files and restore `partE-ic.tec`
from `../JPL-Eulerian-20micron/INPUT/part-ic.tec`.
EOF
ls "$C" "$C/INPUT"; grep -n "^phase\|^ICE-iter\|^IGLOO-iter\|^krho\|^name\|^modeling" "$C/input.ini"
